34	import {
35	  ArrowLeft,
36	  LayoutTemplate,
37	  Plus,
38	  Save,
39	  Trash2,
40	  Package,
41	  Truck,
42	  Zap,
43	  FileText,
44	  Loader2,
45	  Calculator,
46	  ChefHat,
47	  Wheat,
48	  Receipt,
49	} from 'lucide-react';
50	import { Button } from '@/shared/ui/button';
51	import { Badge } from '@/shared/ui/badge';
52	import { Input } from '@/shared/ui/input';
53	import { Label } from '@/shared/ui/label';
54	import {
55	  Sheet,
56	  SheetContent,
57	  SheetHeader,
58	  SheetTitle,
59	  SheetFooter,
60	} from '@/shared/ui/sheet';
61	import {
62	  Dialog,
63	  DialogContent,
64	  DialogHeader,
65	  DialogTitle,
66	  DialogFooter,
67	} from '@/shared/ui/dialog';
68	import {
69	  Select,
70	  SelectContent,
71	  SelectItem,
