73	  SelectValue,
74	} from '@/shared/ui/select';
75	
76	// ---------------------------------------------------------------------------
77	// HELPERS
78	// ---------------------------------------------------------------------------
79	
80	const fmt = (v: number | null | undefined): string => {
81	  if (typeof v !== 'number') return 'R$ 0,00';
82	  return v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
83	};
84	
85	type TipoItem = 'embalagem' | 'frete' | 'overhead' | 'nf_linked';
86	
87	const TIPO_CONFIG: Record<TipoItem, { label: string; color: string; icon: React.ReactNode }> = {
88	  embalagem: { label: 'Embalagem', color: 'bg-blue-600/80 border-blue-400/40', icon: <Package size={12} /> },
89	  frete: { label: 'Frete', color: 'bg-orange-600/80 border-orange-400/40', icon: <Truck size={12} /> },
90	  overhead: { label: 'Overhead', color: 'bg-purple-600/80 border-purple-400/40', icon: <Zap size={12} /> },
91	  nf_linked: { label: 'NF Vinculada', color: 'bg-cyan-600/80 border-cyan-400/40', icon: <FileText size={12} /> },
92	};
93	
94	const STATUS_COLORS: Record<string, string> = {
95	  rascunho: 'bg-zinc-700 text-zinc-300',
96	  aprovada: 'bg-emerald-800 text-emerald-300',
97	  obsoleta: 'bg-zinc-800 text-zinc-500',
98	};
99	
100	// ---------------------------------------------------------------------------
101	// CUSTOM NODE COMPONENTS
102	// ---------------------------------------------------------------------------
103	
104	interface CmvRootNodeData extends Record<string, unknown> {
105	  nome: string;
106	  custo: number | null;
107	  status: string;
108	}
109	
110	const CmvRootNode = memo(function CmvRootNode({ data }: NodeProps<CmvRootNodeData>) {
111	  return (
112	    <div className="relative px-5 py-4 rounded-2xl border border-[#57715B]/50 bg-[#57715B]/90 backdrop-blur-md text-white min-w-[260px] shadow-2xl shadow-[#57715B]/40">
113	      <div className="flex items-start justify-between mb-2 gap-2">
114	        <div className="flex items-center gap-1.5 opacity-80">
115	          <Calculator size={12} />
116	          <span className="text-[9px] font-bold uppercase tracking-wider">CMV Central</span>
117	        </div>
118	        <span className={`text-[9px] px-2 py-0.5 rounded-full font-bold uppercase tracking-wide ${STATUS_COLORS[data.status] ?? STATUS_COLORS.rascunho}`}>
119	          {data.status}
120	        </span>
121	      </div>
122	      <h3 className="text-base font-bold truncate leading-tight mb-2">{data.nome}</h3>
123	      <p className="text-2xl font-black tabular-nums">{fmt(data.custo)}</p>
124	      <Handle type="target" position={Position.Left} className="!w-3.5 !h-3.5 !bg-white/60 !border-2 !border-white/30" />
125	    </div>
126	  );
127	});
128	
129	interface FichaBaseNodeData extends Record<string, unknown> {
130	  nome: string;
131	  custoUnitario: number;
132	  rendimento: string;
133	  status: string;
134	}
135	
136	const FichaBaseNode = memo(function FichaBaseNode({ data }: NodeProps<FichaBaseNodeData>) {
137	  return (
138	    <div className="relative px-5 py-4 rounded-2xl border border-amber-500/40 bg-amber-700/80 backdrop-blur-md text-white min-w-[240px] shadow-xl shadow-amber-700/30">
139	      <div className="flex items-center gap-1.5 opacity-80 mb-2">
140	        <ChefHat size={12} />
141	        <span className="text-[9px] font-bold uppercase tracking-wider">Ficha Técnica Base</span>
142	      </div>
143	      <h3 className="text-base font-semibold truncate mb-1">{data.nome}</h3>
144	      <div className="flex items-end justify-between mt-2">
145	        <div>
146	          <p className="text-[9px] opacity-60 leading-none mb-0.5">Custo unitário</p>
147	          <p className="text-xl font-bold tabular-nums">{fmt(data.custoUnitario)}</p>
148	        </div>
149	        <span className="text-[10px] px-2 py-0.5 bg-white/20 rounded-full">{data.rendimento}</span>
150	      </div>
151	      <Handle type="source" position={Position.Right} className="!w-3 !h-3 !bg-amber-300 !border-2 !border-white" />
152	    </div>
153	  );
154	});
155	
156	interface CmvItemNodeData extends Record<string, unknown> {
157	  tipo: TipoItem;
158	  quantidade: number;
159	  unidade: string;
160	  custo: number | null;
161	  label: string;
162	}
163	
164	const CmvItemNode = memo(function CmvItemNode({ data, selected }: NodeProps<CmvItemNodeData>) {
165	  const cfg = TIPO_CONFIG[data.tipo] ?? TIPO_CONFIG.overhead;
166	  return (
167	    <div className={`relative px-4 py-3 rounded-xl border backdrop-blur-md text-zinc-100 min-w-[200px] shadow-lg transition-all duration-150 ${cfg.color} ${selected ? 'ring-2 ring-white/40 scale-[1.02]' : 'hover:shadow-xl hover:-translate-y-0.5'}`}>
168	      <div className="flex items-center gap-1.5 mb-2">
169	        <span className="opacity-80">{cfg.icon}</span>
170	        <span className="text-[9px] font-bold uppercase tracking-wider opacity-80">{cfg.label}</span>
171	      </div>
172	      <h4 className="text-sm font-semibold truncate mb-1.5">{data.label}</h4>
173	      <div className="flex items-end justify-between">
174	        <span className="text-[11px] text-white/70">{data.quantidade} {data.unidade}</span>
175	        <span className="text-base font-bold tabular-nums">{fmt(data.custo)}</span>
176	      </div>
177	      <Handle type="target" position={Position.Left} className="!w-2.5 !h-2.5 !bg-white/40 !border-2 !border-white/20" />
178	      <Handle type="source" position={Position.Right} className="!w-2.5 !h-2.5 !bg-white/60 !border-2 !border-white/30" />
179	    </div>
180	  );
181	});
182	
183	interface InsumoNodeData extends Record<string, unknown> {
184	  nome: string;
185	  preco: number | null;
186	  unidade: string;
187	}
188	
189	const InsumoNode = memo(function InsumoNode({ data }: NodeProps<InsumoNodeData>) {
190	  return (
191	    <div className="px-3 py-2 rounded-lg border border-violet-400/30 bg-violet-700/70 backdrop-blur-sm text-white min-w-[180px] shadow-md">
192	      <div className="flex items-center gap-1 mb-1 opacity-70">
193	        <Wheat size={10} />
194	        <span className="text-[9px] font-bold uppercase">Insumo</span>
195	      </div>
196	      <h4 className="text-xs font-semibold truncate">{data.nome}</h4>
197	      <p className="text-sm font-bold tabular-nums">
198	        {fmt(data.preco)} <span className="text-[9px] font-normal opacity-60">/{data.unidade}</span>
199	      </p>
200	      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-violet-300 !border-2 !border-white" />
201	    </div>
202	  );
203	});
204	
205	interface NFNodeData extends Record<string, unknown> {
206	  fornecedor: string;
207	  numero: string | null;
208	  valor: number | null;
209	}
210	
211	const NFNode = memo(function NFNode({ data }: NodeProps<NFNodeData>) {
212	  return (
213	    <div className="px-3 py-2 rounded-lg border border-cyan-400/30 bg-cyan-700/70 backdrop-blur-sm text-white min-w-[160px] shadow-md">
214	      <div className="flex items-center gap-1 mb-1 opacity-70">
215	        <Receipt size={10} />
216	        <span className="text-[9px] font-bold uppercase">Nota Fiscal</span>
217	      </div>
218	      <h4 className="text-[11px] font-semibold truncate">{data.fornecedor || 'Fornecedor'}</h4>
219	      {data.numero && <p className="text-[9px] opacity-60">#{data.numero}</p>}
220	      <p className="text-xs font-bold tabular-nums">{fmt(data.valor)}</p>
221	      <Handle type="source" position={Position.Right} className="!w-2 !h-2 !bg-cyan-300 !border-2 !border-white" />
222	    </div>
223	  );
224	});
225	
226	const nodeTypes: NodeTypes = {
227	  cmv: CmvRootNode,
228	  ficha: FichaBaseNode,
229	  cmvItem: CmvItemNode,
230	  insumo: InsumoNode,
231	  nf: NFNode,
232	};
233	
234	// ---------------------------------------------------------------------------
235	// INNER COMPONENT (usa useReactFlow())
236	// ---------------------------------------------------------------------------
237	
238	function CmvConfiguratorInner() {
239	  const navigate = useNavigate();
240	  const [searchParams] = useSearchParams();
241	  const cmvIdParam = searchParams.get('focus');
242	  const cmvId = cmvIdParam !== null && cmvIdParam !== '' ? parseInt(cmvIdParam, 10) : null;
243	
244	  const {
245	    loading,
246	    cmv,
247	    fichaData,
248	    items,
249	    insumos,
250	    positions,
251	    savePosition,
252	    refetch,
253	  } = useCmvGraph(cmvId);
254	
255	  const { fitView } = useReactFlow();
256	  const queryClient = useQueryClient();
257	  const [nodes, setNodes, onNodesChange] = useNodesState([]);
258	  const [edges, setEdges, onEdgesChange] = useEdgesState([]);
259	
260	  // Detail panel state
261	  const [selectedItemData, setSelectedItemData] = useState<RawCmvItem | null>(null);
262	  const [editQty, setEditQty] = useState('');
263	  const [editUnit, setEditUnit] = useState('');
264	  const [editPreco, setEditPreco] = useState('');
265	  const [editObs, setEditObs] = useState('');
266	  const [isSaving, setIsSaving] = useState(false);
267	  const [isDeleting, setIsDeleting] = useState(false);
268	
269	  // Add item dialog state
270	  const [isAddOpen, setIsAddOpen] = useState(false);
271	  const [newTipo, setNewTipo] = useState<TipoItem>('embalagem');
272	  const [newQty, setNewQty] = useState('1');
273	  const [newUnit, setNewUnit] = useState('un');
274	  const [newPreco, setNewPreco] = useState('');
275	  const [newObs, setNewObs] = useState('');
276	  const [isAddSaving, setIsAddSaving] = useState(false);
277	
278	  // -------------------------------------------------------------------------
279	  // Build ReactFlow nodes/edges from hook data
280	  // -------------------------------------------------------------------------
281	  const buildGraph = useCallback(() => {
282	    if (!cmv) return;
283	
284	    const newNodes: Node[] = [];
285	    const newEdges: Edge[] = [];
286	
287	    const rootId = cmvNodeId(cmv.id);
288	
289	    // Root node
290	    newNodes.push({
291	      id: rootId,
292	      type: 'cmv',
293	      data: { nome: cmv.nome, custo: cmv.custo_calculado, status: cmv.status, kind: 'cmv' } as Record<string, unknown>,
294	      position: positions.get(rootId) ?? { x: 800, y: 300 },
295	    });
296	
297	    // Ficha base node
298	    if (fichaData) {
299	      const fId = fichaNodeId(fichaData.id);
300	      const rendQty = fichaData.rendimento_quantidade || 1;
301	      const custoUnitario = (fichaData.custo_calculado ?? 0) / rendQty;
302	
303	      newNodes.push({
304	        id: fId,
305	        type: 'ficha',
306	        data: {
307	          nome: fichaData.nome,
308	          custoUnitario,
309	          rendimento: `${fichaData.rendimento_quantidade} ${fichaData.rendimento_unidade}`,
310	          status: fichaData.status,
311	          kind: 'ficha',
312	        } as Record<string, unknown>,
313	        position: positions.get(fId) ?? { x: 400, y: 300 },
314	      });
315	
316	      newEdges.push({
317	        id: `e-${fId}-${rootId}`,
318	        source: fId,
319	        target: rootId,
320	        animated: true,
321	        style: { stroke: '#F59E0B', strokeWidth: 3 },
322	      });
323	    }
324	
325	    // Item nodes
326	    const addedInsumoIds = new Set<number>();
327	
328	    items.forEach((item, idx) => {
329	      const itemId = `item_${item.id}`;
330	      const label = item.insumo?.nome ?? item.observacao ?? `Item ${idx + 1}`;
331	
332	      newNodes.push({
333	        id: itemId,
334	        type: 'cmvItem',
335	        data: {
336	          tipo: item.tipo as TipoItem,
337	          quantidade: item.quantidade,
338	          unidade: item.unidade,
339	          custo: item.custo_calculado,
340	          label,
341	          kind: 'cmvItem',
342	          _rawItemId: item.id,
343	        } as Record<string, unknown>,
344	        position: positions.get(itemId) ?? { x: 400, y: 100 + idx * 160 },
345	      });
346	
347	      newEdges.push({
348	        id: `e-${itemId}-${rootId}`,
349	        source: itemId,
350	        target: rootId,
351	        style: { stroke: '#52525b', strokeWidth: 2 },
352	      });
353	
354	      // Insumo linked to item
355	      if (item.insumo_id && !addedInsumoIds.has(item.insumo_id)) {
356	        addedInsumoIds.add(item.insumo_id);
357	        const insId = insumoNodeId(item.insumo_id);
358	        const insData = insumos.find((i) => i.id === item.insumo_id);
359	
360	        newNodes.push({
361	          id: insId,
362	          type: 'insumo',
363	          data: {
364	            nome: insData?.nome ?? 'Insumo',
365	            preco: insData?.preco_custo ?? null,
366	            unidade: insData?.unidade_compra ?? 'un',
367	            kind: 'insumo',
368	          } as Record<string, unknown>,
369	          position: positions.get(insId) ?? { x: 100, y: 100 + idx * 160 },
370	        });
371	
372	        newEdges.push({
373	          id: `e-${insId}-${itemId}`,
374	          source: insId,
375	          target: itemId,
376	          style: { stroke: '#7c3aed', strokeWidth: 1.5 },
377	        });
378	      }
379	    });
380	
381	    // Apply dagre layout for nodes without saved positions
382	    const hasAllPositions = newNodes.every((n) => positions.has(n.id));
383	    if (!hasAllPositions && newNodes.length > 0) {
384	      const laid = layoutGraph(newNodes, newEdges, 'LR');
385	      setNodes(laid);
386	    } else {
387	      setNodes(newNodes);
388	    }
389	    setEdges(newEdges);
390	
391	    setTimeout(() => {
392	      fitView({ padding: 0.12, duration: 400 });
393	    }, 80);
394	  }, [cmv, fichaData, items, insumos, positions, fitView, setNodes, setEdges]);
395	
396	  useEffect(() => {
397	    if (!loading) {
398	      buildGraph();
399	    }
400	  }, [loading, buildGraph]);
401	
402	  // -------------------------------------------------------------------------
403	  // Node drag → save position
404	  // -------------------------------------------------------------------------
405	  const handleNodeDragStop: NodeDragHandler = useCallback(
406	    (_evt, node) => {
407	      savePosition(node.id, node.position.x, node.position.y);
408	    },
409	    [savePosition],
410	  );
411	
412	  // -------------------------------------------------------------------------
413	  // Node click → open detail panel
414	  // -------------------------------------------------------------------------
415	  const handleNodeClick = useCallback(
416	    (_evt: React.MouseEvent, node: Node) => {
417	      const rawId = (node.data as Record<string, unknown>)._rawItemId;
418	      if (typeof rawId !== 'number') {
419	        setSelectedItemData(null);
420	        return;
421	      }
422	      const found = items.find((it) => it.id === rawId);
423	      if (found) {
424	        setSelectedItemData(found);
425	        setEditQty(String(found.quantidade));
426	        setEditUnit(found.unidade);
427	        setEditPreco(found.preco_unitario_esboco !== null ? String(found.preco_unitario_esboco) : '');
428	        setEditObs(found.observacao ?? '');
429	      }
430	    },
431	    [items],
432	  );
433	
434	  // -------------------------------------------------------------------------
435	  // Auto-layout
436	  // -------------------------------------------------------------------------
437	  const handleAutoLayout = useCallback(() => {
438	    setNodes((prev) => {
439	      const laid = layoutGraph(prev, edges, 'LR');
440	      laid.forEach((n) => savePosition(n.id, n.position.x, n.position.y));
441	      return laid;
442	    });
443	    setTimeout(() => fitView({ padding: 0.12, duration: 400 }), 80);
444	  }, [edges, fitView, savePosition, setNodes]);
445	
446	  // -------------------------------------------------------------------------
447	  // Save item
448	  // -------------------------------------------------------------------------
449	  const handleSaveItem = useCallback(async () => {
450	    if (!selectedItemData) return;
451	    setIsSaving(true);
452	    const { error } = await supabase
453	      .from('cmv_itens')
454	      .update({
455	        quantidade: parseFloat(editQty) || selectedItemData.quantidade,
456	        unidade: editUnit,
457	        preco_unitario_esboco: editPreco !== '' ? parseFloat(editPreco) : null,
458	        observacao: editObs || null,
459	      })
460	      .eq('id', selectedItemData.id);
461	
462	    if (error) {
463	      toast.error(`Erro ao salvar: ${error.message}`);
464	    } else {
465	      toast.success('Item atualizado!');
466	      setSelectedItemData(null);
467	      await refetch();
468	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
469	    }
470	    setIsSaving(false);
471	  }, [selectedItemData, editQty, editUnit, editPreco, editObs, refetch, queryClient]);
472	
473	  // -------------------------------------------------------------------------
474	  // Delete item
475	  // -------------------------------------------------------------------------
476	  const handleDeleteItem = useCallback(async () => {
477	    if (!selectedItemData) return;
478	    setIsDeleting(true);
479	    const { error } = await supabase
480	      .from('cmv_itens')
481	      .delete()
482	      .eq('id', selectedItemData.id);
483	
484	    if (error) {
485	      toast.error(`Erro ao excluir: ${error.message}`);
486	    } else {
487	      toast.success('Item removido!');
488	      setSelectedItemData(null);
489	      await refetch();
490	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
491	    }
492	    setIsDeleting(false);
493	  }, [selectedItemData, refetch, queryClient]);
494	
495	  // -------------------------------------------------------------------------
496	  // Add item
497	  // -------------------------------------------------------------------------
498	  const handleAddItem = useCallback(async () => {
499	    if (!cmvId) return;
500	    setIsAddSaving(true);
501	    const { error } = await supabase.from('cmv_itens').insert({
502	      cmv_id: cmvId,
503	      tipo: newTipo,
504	      quantidade: parseFloat(newQty) || 1,
505	      unidade: newUnit,
506	      preco_unitario_esboco: newPreco !== '' ? parseFloat(newPreco) : null,
507	      observacao: newObs || null,
508	      ordem: items.length,
509	    });
510	
511	    if (error) {
512	      toast.error(`Erro ao criar item: ${error.message}`);
513	    } else {
514	      toast.success('Item adicionado!');
515	      setIsAddOpen(false);
516	      setNewTipo('embalagem');
517	      setNewQty('1');
518	      setNewUnit('un');
519	      setNewPreco('');
520	      setNewObs('');
521	      await refetch();
522	      queryClient.invalidateQueries({ queryKey: ['cmv_fichas'] });
523	    }
524	    setIsAddSaving(false);
525	  }, [cmvId, newTipo, newQty, newUnit, newPreco, newObs, items.length, refetch, queryClient]);
526	
527	  // -------------------------------------------------------------------------
528	  // Empty/loading states
529	  // -------------------------------------------------------------------------
530	  if (!cmvId) {
531	    return (
532	      <div className="h-[100dvh] bg-[#0F1117] flex flex-col items-center justify-center text-zinc-400">
533	        <Calculator className="h-12 w-12 mb-4 text-[#57715B]" />
534	        <p className="text-sm mb-4">Nenhum CMV selecionado</p>
535	        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
536	          <ArrowLeft className="mr-2 h-4 w-4" />
537	          Voltar ao CMV
538	        </Button>
539	      </div>
540	    );
541	  }
542	
543	  if (loading) {
544	    return (
545	      <div className="h-[100dvh] bg-[#0F1117] flex items-center justify-center">
546	        <Loader2 className="h-8 w-8 animate-spin text-[#57715B]" />
547	      </div>
548	    );
549	  }
550	
551	  if (!cmv) {
552	    return (
553	      <div className="h-[100dvh] bg-[#0F1117] flex flex-col items-center justify-center text-zinc-400">
554	        <p className="text-sm mb-4">CMV não encontrado.</p>
555	        <Button variant="outline" onClick={() => navigate('/financeiro/cmv')}>
556	          <ArrowLeft className="mr-2 h-4 w-4" />
557	          Voltar
558	        </Button>
559	      </div>
560	    );
561	  }
562	
563	  // -------------------------------------------------------------------------
564	  // Render
565	  // -------------------------------------------------------------------------
566	  return (
567	    <div className="h-screen w-screen bg-[#0F1117] overflow-hidden">
568	      <ReactFlow
569	        nodes={nodes}
570	        edges={edges}
